\pset pager off
SELECT pid, application_name, state, wait_event_type, wait_event, round(extract(epoch from now()-xact_start)) AS xact_s, round(extract(epoch from now()-query_start)) AS query_s, left(regexp_replace(query, '\s+', ' ', 'g'), 150) AS q FROM pg_stat_activity WHERE datname IS NOT NULL AND pid <> pg_backend_pid() AND (state <> 'idle' OR wait_event_type = 'Lock') ORDER BY xact_s DESC NULLS LAST LIMIT 15;
SELECT 'blocked', blocked.pid AS blocked_pid, blocking.pid AS blocking_pid, left(regexp_replace(blocking.query, '\s+', ' ', 'g'), 120) AS blocking_q FROM pg_locks bl JOIN pg_stat_activity blocked ON blocked.pid = bl.pid AND NOT bl.granted JOIN pg_locks kl ON kl.locktype = bl.locktype AND kl.database IS NOT DISTINCT FROM bl.database AND kl.relation IS NOT DISTINCT FROM bl.relation AND kl.transactionid IS NOT DISTINCT FROM bl.transactionid AND kl.granted JOIN pg_stat_activity blocking ON blocking.pid = kl.pid LIMIT 10;
